package com.clemente.clementime;
import android.app.Activity; import android.appwidget.AppWidgetManager; import android.content.ComponentName; import android.os.Bundle; import android.view.View;
public class ThemeConfigActivity extends Activity { private int id=AppWidgetManager.INVALID_APPWIDGET_ID; @Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.config_theme);id=getIntent().getIntExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,AppWidgetManager.INVALID_APPWIDGET_ID);} public void selectTheme(View v){int t;try{t=Integer.parseInt(String.valueOf(v.getTag()));}catch(Exception e){t=0;}AppWidgetManager m=AppWidgetManager.getInstance(this);ClementimeWidgetProvider.setDefaultTheme(this,t);if(id!=AppWidgetManager.INVALID_APPWIDGET_ID)ClementimeWidgetProvider.setTheme(this,m,id,t);else for(int x:m.getAppWidgetIds(new ComponentName(this,ClementimeWidgetProvider.class)))ClementimeWidgetProvider.setTheme(this,m,x,t);finish();} }
